const bridgeB = bucketed(bridgeBits);
const towers = BRIDGE_X.flatMap(bx => TOWERS.map(y => ({ x: bx * 8 + 1, y: mod(y, N) })));

// street food: a rare cart at the curb, a few kinds. Two art frames each so the steam/umbrella shimmer.
