    const wu = fract(u * 4);
    if (wu > 0.2 && wu < 0.8 && fz > 0.3 && fz < 0.85)
      return hash(Math.floor(u * 4), fl, sk) > litT - 0.05 ? set(i, '#', C(WARM, Math.max(L, glowL))) : set(i, '.', C(GRAY, L * 0.3));
    if (fz < 0.08) return set(i, '_', C(WARM, L * 0.6)); // floor line
