      const onHand = (A, len) => rr < len && Math.abs(mod(ang - A + Math.PI, 2 * Math.PI) - Math.PI) * Math.max(rr, 0.06) < 0.05;
      BG[i] = C(WHITE, Math.max(8 * amb, night * 11)); // the face glows at night
